  "contradictory_card_ids": ["C52", "C55", "C57", "C60", "C61", "C63"],
  "prediction_basis_card_ids": ["C05", "C01", "C03", "C12", "C28", "C34", "C35", "C38"],
  "claims": [
    {
      "claim": "The query is a permanently charged quaternary ammonium tropane ester; direct low-F evidence for the quaternary ammonium class (diphemanil methylsulphate, very low oral bioavailability after a 250 mg oral dose) and for strongly cationic molecules (DX-9065, human F 2–3%, 2.8±1.5% for a conventional capsule) supports F < 20%.",
      "card_ids": ["C05", "C01", "C03", "C12"]
    },
    {
      "claim": "Oral exposure records for quaternary ammonium antimuscarinics show pg/mL Cmax after milligram oral doses (trospium 60 mg XR Cmax 1517–1873 pg/mL; glycopyrrolate 2 mg Cmax 318 pg/mL), consistent with poor systemic absorption and low F.",
      "card_ids": ["C28", "C34", "C35", "C38"]
    },
    {
      "claim": "L5 shows that some quaternary ammonium tropanes are inferred substrates of absorptive transporters (ipratropium and tiotropium for OCTN2; trospium for OCT1) and that ion-pairing can enhance propantheline absorption, but these are mechanistic observations and do not establish F ≥ 20%.",
      "card_ids": ["C55", "C60", "C57", "C61", "C63"]
    },
    {
      "claim": "Trospium's OCT1 uptake (C57/C61) coexists with pg/mL Cmax after oral dosing (C28/C35), indicating transporter-mediated uptake does not by itself overcome the low oral bioavailability of this quaternary ammonium class.",
      "card_ids": ["C57", "C61", "C28", "C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C52", "C55", "C57", "C60", "C61", "C63"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No matched oral versus intravenous exposure data are available for the query.",
    "No direct permeability or efflux measurement for the query; transporter substrate status is inferred from close analogs (ipratropium, tiotropium, trospium).",
    "L5 provides no measured F value for any quaternary ammonium tropane; OCTN2/OCT1 substrate status alone is not threshold-relevant.",
    "Differences in ester hydrolysis, intestinal metabolism, formulation, and dose between the query and cited analogs are unmeasured.",
    "The reported neutral fraction of 1 is inconsistent with the quaternary ammonium structure and was not used as evidence."
  ],
  "decision_summary": "Predicted low: the query is a permanently charged quaternary ammonium tropane ester. Direct low-F evidence for the quaternary ammonium/cationic class (diphemanil, DX-9065) and pg/mL Cmax for quaternary ammonium antimuscarinics (trospium, glycopyrrolate) support F < 20%. L5 adds mechanistic evidence that some quaternary ammonium tropanes are substrates of absorptive transporters (OCTN2/OCT1) and can undergo ion-pair-enhanced absorption, which modestly weakens the low case, but these mechanisms do not establish F ≥ 20%, and trospium's OCT1 uptake coexists with pg/mL oral Cmax. Confidence remains moderate."
}

